CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE memberships(user_id uuid REFERENCES users, entity_id uuid REFERENCES entities, role text NOT NULL CHECK(role IN ('owner','manager','sales','market','procurement','finance','viewer')), PRIMARY KEY(user_id,entity_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE records_base(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, business_entity_id uuid NOT NULL REFERENCES entities, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users, updated_by uuid REFERENCES users, row_version integer NOT NULL DEFAULT 1, is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE sources(LIKE records_base INCLUDING ALL, name text NOT NULL, kind text NOT NULL, body text NOT NULL DEFAULT '', storage_key text, mime text, sha256 text, size integer, allowed_use text NOT NULL DEFAULT 'internal');
CREATE TABLE market_tasks(LIKE records_base INCLUDING ALL, name text NOT NULL, status text NOT NULL DEFAULT 'draft', revision integer NOT NULL DEFAULT 1, countries text[] NOT NULL DEFAULT '{}', categories text[] NOT NULL DEFAULT '{}', languages text[] NOT NULL DEFAULT '{en}', makes text[] NOT NULL DEFAULT '{}', exclusions text NOT NULL DEFAULT '', goal integer NOT NULL DEFAULT 20, budget numeric(20,6) NOT NULL DEFAULT 0 CHECK(budget>=0), currency text NOT NULL DEFAULT 'USD', owner_id uuid REFERENCES users);
CREATE TABLE market_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES market_tasks, revision integer NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,revision));
CREATE TABLE activities(LIKE records_base INCLUDING ALL, name text NOT NULL, type text NOT NULL CHECK(type IN ('exhibition','online')), status text NOT NULL DEFAULT 'planned', country text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'Asia/Shanghai', start_at timestamptz, end_at timestamptz, venue text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', owner_id uuid REFERENCES users, budget numeric(20,6) NOT NULL DEFAULT 0 CHECK(budget>=0), currency text NOT NULL DEFAULT 'USD', market_revision_id uuid REFERENCES market_revisions, public_key uuid NOT NULL UNIQUE DEFAULT gen_random_uuid());
CREATE TABLE activity_costs(LIKE records_base INCLUDING ALL, activity_id uuid NOT NULL REFERENCES activities, category text NOT NULL, amount numeric(20,6) NOT NULL CHECK(amount>=0), currency text NOT NULL, source_id uuid NOT NULL REFERENCES sources);
CREATE TABLE accounts(LIKE records_base INCLUDING ALL, name text NOT NULL, country text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', company_type text NOT NULL DEFAULT 'unknown', lifecycle text NOT NULL DEFAULT 'needs_research', owner_id uuid REFERENCES users, merged_into uuid REFERENCES accounts, preferences text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'unverified');
CREATE TABLE contacts(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', title text NOT NULL DEFAULT '', permission text NOT NULL DEFAULT 'unknown' CHECK(permission IN ('unknown','granted','withdrawn')), permission_source_id uuid REFERENCES sources, UNIQUE(account_id,email));
CREATE TABLE suppressions(business_entity_id uuid NOT NULL REFERENCES entities, endpoint text NOT NULL, channel text NOT NULL DEFAULT 'email', reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_entity_id,endpoint,channel));
CREATE TABLE leads(LIKE records_base INCLUDING ALL, activity_id uuid NOT NULL REFERENCES activities, source_id uuid NOT NULL REFERENCES sources, event_id text NOT NULL, payload_hash text NOT NULL, company text NOT NULL, contact_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', classification text NOT NULL DEFAULT 'unknown', permission text NOT NULL DEFAULT 'unknown', status text NOT NULL DEFAULT 'needs_verification', account_id uuid REFERENCES accounts, contact_id uuid REFERENCES contacts, assigned_to uuid REFERENCES users, utm jsonb NOT NULL DEFAULT '{}', UNIQUE(business_entity_id,activity_id,event_id));
CREATE TABLE touches(LIKE records_base INCLUDING ALL, lead_id uuid NOT NULL UNIQUE REFERENCES leads, activity_id uuid NOT NULL REFERENCES activities, account_id uuid REFERENCES accounts, contact_id uuid REFERENCES contacts, source_id uuid NOT NULL REFERENCES sources, occurred_at timestamptz NOT NULL DEFAULT now(), channel text NOT NULL, utm jsonb NOT NULL DEFAULT '{}');
CREATE TABLE facts(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, field text NOT NULL, value text NOT NULL, fact_status text NOT NULL CHECK(fact_status IN ('unknown','extracted','inferred','confirmed','conflicted')), source_id uuid REFERENCES sources, locator text NOT NULL DEFAULT '', confirmed_by uuid REFERENCES users);
CREATE TABLE assessments(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, dimensions jsonb NOT NULL, known_score numeric, coverage numeric NOT NULL, policy_version text NOT NULL DEFAULT 'manual-v1', confirmed_grade text, reason text NOT NULL DEFAULT '');
CREATE TABLE tasks(LIKE records_base INCLUDING ALL, account_id uuid REFERENCES accounts, lead_id uuid REFERENCES leads, title text NOT NULL, kind text NOT NULL DEFAULT 'verify', owner_id uuid REFERENCES users, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','waiting_customer','waiting_internal','completed','cancelled')), check_again_at timestamptz, result text NOT NULL DEFAULT '');
CREATE TABLE opportunities(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, name text NOT NULL, need text NOT NULL DEFAULT '', stage text NOT NULL DEFAULT 'initial', primary_activity_id uuid REFERENCES activities, owner_id uuid REFERENCES users);
CREATE TABLE knowledge(LIKE records_base INCLUDING ALL, name text NOT NULL, kind text NOT NULL DEFAULT 'company', body text NOT NULL, source_id uuid NOT NULL REFERENCES sources, revision integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','revoked')), valid_until timestamptz NOT NULL, share_scope text NOT NULL DEFAULT 'internal' CHECK(share_scope IN ('internal','external','public')), approved_by uuid REFERENCES users);
CREATE TABLE contents(LIKE records_base INCLUDING ALL, activity_id uuid NOT NULL REFERENCES activities, title text NOT NULL, body text NOT NULL, language text NOT NULL DEFAULT 'en', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review_pending','approved','published','revoked')), revision integer NOT NULL DEFAULT 1, knowledge_ids uuid[] NOT NULL DEFAULT '{}', approved_by uuid REFERENCES users, publication_url text, published_at timestamptz);
CREATE TABLE channel_accounts(LIKE records_base INCLUDING ALL, address text NOT NULL, channel text NOT NULL DEFAULT 'email', name text NOT NULL, status text NOT NULL DEFAULT 'manual', UNIQUE(business_entity_id,address));
CREATE TABLE conversations(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, contact_id uuid NOT NULL REFERENCES contacts, channel_account_id uuid NOT NULL REFERENCES channel_accounts, subject text NOT NULL, external_thread_id text NOT NULL, last_inbound_at timestamptz, UNIQUE(channel_account_id,external_thread_id));
CREATE TABLE messages(LIKE records_base INCLUDING ALL, conversation_id uuid NOT NULL REFERENCES conversations, event_id text NOT NULL, direction text NOT NULL CHECK(direction IN ('inbound','draft','outbound_registered')), body text NOT NULL, classification text NOT NULL DEFAULT 'unknown', source_id uuid REFERENCES sources, status text NOT NULL, knowledge_ids uuid[] NOT NULL DEFAULT '{}', UNIQUE(conversation_id,event_id));
CREATE TABLE enrollments(LIKE records_base INCLUDING ALL, contact_id uuid NOT NULL REFERENCES contacts, conversation_id uuid NOT NULL REFERENCES conversations, status text NOT NULL DEFAULT 'active', next_check_at timestamptz NOT NULL, plan text NOT NULL, stopped_reason text);
CREATE TABLE rfqs(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, contact_id uuid REFERENCES contacts, source_id uuid NOT NULL REFERENCES sources, opportunity_id uuid REFERENCES opportunities, title text NOT NULL, destination text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'needs_clarification');
CREATE TABLE rfq_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id uuid NOT NULL REFERENCES rfqs, line_no integer NOT NULL, oe text NOT NULL DEFAULT '', description text NOT NULL, quantity numeric(20,6) CHECK(quantity>0), unit text NOT NULL DEFAULT '', quality text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'needs_clarification', product_id uuid, UNIQUE(rfq_id,line_no));
CREATE TABLE discovery_runs(LIKE records_base INCLUDING ALL, market_revision_id uuid NOT NULL REFERENCES market_revisions, mode text NOT NULL CHECK(mode IN ('import','search')), status text NOT NULL DEFAULT 'running', checkpoint integer NOT NULL DEFAULT 0, stop_reason text, queries jsonb NOT NULL, cost numeric(20,6), currency text NOT NULL DEFAULT 'USD');
CREATE TABLE candidates(LIKE records_base INCLUDING ALL, run_id uuid NOT NULL REFERENCES discovery_runs, source_id uuid NOT NULL REFERENCES sources, entry_key text NOT NULL, company text NOT NULL, email text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', account_id uuid REFERENCES accounts, UNIQUE(run_id,entry_key));
CREATE TABLE budget_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES market_tasks, action_key text NOT NULL, reserved numeric(20,6) NOT NULL CHECK(reserved>=0), actual numeric(20,6), status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','settled','released')), UNIQUE(task_id,action_key));
CREATE TABLE jobs(LIKE records_base INCLUDING ALL, kind text NOT NULL, source_id uuid NOT NULL REFERENCES sources, input_version integer NOT NULL, status text NOT NULL DEFAULT 'queued', model text, result jsonb, error text, usage jsonb, cost numeric, attempts integer NOT NULL DEFAULT 0, locked_at timestamptz, finished_at timestamptz);
CREATE TABLE work_logs(LIKE records_base INCLUDING ALL, category text NOT NULL, minutes integer NOT NULL CHECK(minutes>0), note text NOT NULL DEFAULT '');
CREATE TABLE feedback(LIKE records_base INCLUDING ALL, object_type text NOT NULL, object_id uuid NOT NULL, field text NOT NULL, before_value text NOT NULL, after_value text NOT NULL, reason text NOT NULL, minutes integer NOT NULL CHECK(minutes>0), status text NOT NULL DEFAULT 'pending_review');
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_entity_id uuid NOT NULL REFERENCES entities, actor_id uuid REFERENCES users, action text NOT NULL, object_type text NOT NULL, object_id uuid, detail jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION prevent_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit is append only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_change();
CREATE INDEX accounts_entity_owner ON accounts(business_entity_id,owner_id,updated_at);
CREATE INDEX tasks_entity_due ON tasks(business_entity_id,status,due_at);
CREATE INDEX leads_entity ON leads(business_entity_id,activity_id,created_at);
CREATE INDEX jobs_queue ON jobs(status,created_at);
CREATE INDEX audit_entity ON audit_events(business_entity_id,occurred_at);
